import{_ as t,c as o,o as r,aj as a}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: FunctionInvokeResult<TOutput>","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/FunctionInvokeResult.md","filePath":"reference/js-bao-wss-client/api/interfaces/FunctionInvokeResult.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/FunctionInvokeResult.md"};function s(i,e,c,d,l,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / FunctionInvokeResult</p><h1 id="interface-functioninvokeresult-toutput" tabindex="-1">Interface: FunctionInvokeResult&lt;TOutput&gt; <a class="header-anchor" href="#interface-functioninvokeresult-toutput" aria-label="Permalink to “Interface: FunctionInvokeResult&lt;TOutput&gt;”">​</a></h1><p>The invoke envelope.</p><p>Deliberately without a <code>runId</code>: the request path writes no run row, so there is nothing to look up afterwards. A function that throws or times out is a settled invocation with a terminal <code>status</code>, NOT a transport error — only the platform refusing the call before the code ran (access, disabled, unpushed, rate) is an HTTP error.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="toutput" tabindex="-1">TOutput <a class="header-anchor" href="#toutput" aria-label="Permalink to “TOutput”">​</a></h3><p><code>TOutput</code> = <code>unknown</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="error" tabindex="-1">error? <a class="header-anchor" href="#error" aria-label="Permalink to “error?”">​</a></h3><blockquote><p><code>optional</code> <strong>error?</strong>: <code>string</code></p></blockquote><p>Present when <code>status</code> is <code>&quot;failed&quot;</code> or <code>&quot;timeout&quot;</code>.</p><hr><h3 id="errorcode" tabindex="-1">errorCode? <a class="header-anchor" href="#errorcode" aria-label="Permalink to “errorCode?”">​</a></h3><blockquote><p><code>optional</code> <strong>errorCode?</strong>: <code>string</code></p></blockquote><hr><h3 id="invocationid" tabindex="-1">invocationId? <a class="header-anchor" href="#invocationid" aria-label="Permalink to “invocationId?”">​</a></h3><blockquote><p><code>optional</code> <strong>invocationId?</strong>: <code>string</code></p></blockquote><p>The invocation-log record this answer belongs to.</p><p>Minted before the run, so the record and the answer share it: hand it to <code>primitive functions logs &lt;functionId&gt; --invocation &lt;id&gt;</code> to read what the invocation printed and the error it threw.</p><p>Present exactly when the platform recorded the invocation — which is every outcome the function itself produced. Absent from a platform refusal whose record was suppressed, and from a server that predates the field.</p><hr><h3 id="limits" tabindex="-1">limits? <a class="header-anchor" href="#limits" aria-label="Permalink to “limits?”">​</a></h3><blockquote><p><code>optional</code> <strong>limits?</strong>: <a href="./FunctionInvokeLimits.html"><code>FunctionInvokeLimits</code></a></p></blockquote><p>The ceilings the sandbox ran under.</p><p>Present on every outcome the sandbox produced; absent from a refusal that never reached it, which has no run to describe — and those refusals are HTTP errors, so a caller holding this envelope has one.</p><hr><h3 id="output" tabindex="-1">output? <a class="header-anchor" href="#output" aria-label="Permalink to “output?”">​</a></h3><blockquote><p><code>optional</code> <strong>output?</strong>: <code>TOutput</code></p></blockquote><p>Present when <code>status</code> is <code>&quot;completed&quot;</code>.</p><hr><h3 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h3><blockquote><p><strong>status</strong>: <a href="./../type-aliases/FunctionInvokeStatus.html"><code>FunctionInvokeStatus</code></a></p></blockquote>',34)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
